const sharp = require('sharp');
const fs = require('fs');

async function checkArrow() {
  const meta = await sharp('scripts/detailed_refs/travel_arrow.png').metadata();
  console.log('travel_arrow.png:', meta);

  // travel_arrow.png was generated by get_screenshot({ nodeId: '230:74' }) from Figma!
  // It is the EXACT pixel-perfect rasterization from Figma.
  fs.copyFileSync('scripts/detailed_refs/travel_arrow.png', 'public/assets/about/arrow-travel.png');
  console.log('Copied travel_arrow.png to public/assets/about/arrow-travel.png');
}
checkArrow();
